    for  f = 0; f <= p.pPars.iFrame; f++  {
        Vec_IntFillExtra( Ga2_MapFrameMap(p, f), Vec_IntSize(p.vValues), -1 );
        Gia_ManForEachObjVec( vToAdd, p.pGia, pObj, i )
            Ga2_ManAddToAbsOneStatic( p, pObj, f, 1 );
    }
//    sat_solver2_simplify( p->pSat );
}

