    if Lit == -1 {
        return 0; }
    if Abc_Lit2Var(Lit) >= p.pSat.size {
        return 0; }
    return Abc_LitIsCompl(Lit) ^ sat_solver2_var_value( p.pSat, Abc_Lit2Var(Lit) );
}

