func Ga2_ObjCnf0(p *Ga2_Man_t, pObj *Gia_Obj_t) *Vec_Int_t { assert(Ga2_ObjId(p,pObj) >= 0, "Ga2_ObjId(p,pObj) >= 0"); return (Vec_Int_t *)Vec_PtrEntry( p.vCnfs, 2*Ga2_ObjId(p,pObj)   );                  }
func Ga2_ObjCnf1(p *Ga2_Man_t, pObj *Gia_Obj_t) *Vec_Int_t { assert(Ga2_ObjId(p,pObj) >= 0, "Ga2_ObjId(p,pObj) >= 0"); return (Vec_Int_t *)Vec_PtrEntry( p.vCnfs, 2*Ga2_ObjId(p,pObj)+1 );                  }

func Ga2_ObjIsAbs0(p *Ga2_Man_t, pObj *Gia_Obj_t) int32 { assert(Ga2_ObjId(p,pObj) >= 0, "Ga2_ObjId(p,pObj) >= 0"); return Ga2_ObjId(p,pObj) >= 0         && Ga2_ObjId(p,pObj) < p.LimAbs;  }
func Ga2_ObjIsLeaf0(p *Ga2_Man_t, pObj *Gia_Obj_t) int32 { assert(Ga2_ObjId(p,pObj) >= 0, "Ga2_ObjId(p,pObj) >= 0"); return Ga2_ObjId(p,pObj) >= p.LimAbs && Ga2_ObjId(p,pObj) < p.LimPpi;  }
func Ga2_ObjIsAbs(p *Ga2_Man_t, pObj *Gia_Obj_t) int32 { return Ga2_ObjId(p,pObj) >= 0 &&  Ga2_ObjCnf0(p,pObj);                                                   }
func Ga2_ObjIsLeaf(p *Ga2_Man_t, pObj *Gia_Obj_t) int32 { return Ga2_ObjId(p,pObj) >= 0 && !Ga2_ObjCnf0(p,pObj);                                                   }

