//    assert( Lit > 1 );
    assert(Ga2_ObjFindLit(p, pObj, f) == -1, "Ga2_ObjFindLit(p, pObj, f) == -1");
    Vec_IntSetEntry( Ga2_MapFrameMap(p, f), Ga2_ObjId(p,pObj), Lit );
}
// returns or inserts-and-returns literal of this object
func Ga2_ObjFindOrAddLit(p *Ga2_Man_t, pObj *Gia_Obj_t, f int32) int32 { 
    var Lit int32  = Ga2_ObjFindLit( p, pObj, f );
    if Lit == -1 {
