/**Function*************************************************************

  Synopsis    [Computes truth table for the marked node.]

  Description []

  SideEffects []

  SeeAlso     []

***********************************************************************/
func Ga2_ObjComputeTruth_rec(p *Gia_Man_t, pObj *Gia_Obj_t, fFirst int32) uint32 {
    var Val0, Val1 uint32;
    if pObj.fPhase && !(fFirst != 0) {
        return pObj.Value; }
    assert(Gia_ObjIsAnd(pObj), "Gia_ObjIsAnd(pObj)");
    Val0 = Ga2_ObjComputeTruth_rec( p, Gia_ObjFanin0(pObj), 0 );
    Val1 = Ga2_ObjComputeTruth_rec( p, Gia_ObjFanin1(pObj), 0 );
    return (Gia_ObjFaninC0(pObj) ? ~Val0 : Val0) & (Gia_ObjFaninC1(pObj) ? ~Val1 : Val1);
}
var spStatic_Ga2_ManComputeTruth_uTruth5 [5]uint32 = [5]uint32{ 0xAAAAAAAA, 0xCCCCCCCC, 0xF0F0F0F0, 0xFF00FF00, 0xFFFF0000 };
func Ga2_ManComputeTruth(p *Gia_Man_t, pRoot *Gia_Obj_t, vLeaves *Vec_Int_t) uint32 {

    var pObj *Gia_Obj_t;
    var Res uint32;
    var i int32;
    Gia_ManForEachObjVec( vLeaves, p, pObj, i )
        pObj.Value = spStatic_Ga2_ManComputeTruth_uTruth5[i];
    Res = Ga2_ObjComputeTruth_rec( p, pRoot, 1 );
    Gia_ManForEachObjVec( vLeaves, p, pObj, i )
        pObj.Value = 0;
    return Res;
}

/**Function*************************************************************

  Synopsis    [Returns AIG marked for CNF generation.]

  Description [The marking satisfies the following requirements:
  Each marked node has the number of marked fanins no more than N.]

  SideEffects [Uses pObj->fPhase to store the markings.]

  SeeAlso     []

***********************************************************************/
func Ga2_ManBreakTree_rec(p *Gia_Man_t, pObj *Gia_Obj_t, fFirst int32, N int32) int32 {   // breaks a tree rooted at the node into N-feasible subtrees
    var Val0, Val1 int32;
    if pObj.fPhase && !(fFirst != 0) {
        return 1; }
    Val0 = Ga2_ManBreakTree_rec( p, Gia_ObjFanin0(pObj), 0, N );
    Val1 = Ga2_ManBreakTree_rec( p, Gia_ObjFanin1(pObj), 0, N );
    if Val0 + Val1 < N {
        return Val0 + Val1; }
    if Val0 + Val1 == N {
        pObj.fPhase = 1;
        return 1;
    }
    assert(Val0 + Val1 > N, "Val0 + Val1 > N");
    assert(Val0 < N && Val1 < N, "Val0 < N && Val1 < N");
    if Val0 >= Val1 {
        Gia_ObjFanin0(pObj).fPhase = 1;
        Val0 = 1;

    } else {
        Gia_ObjFanin1(pObj).fPhase = 1;
        Val1 = 1;
    }
    if Val0 + Val1 < N {
        return Val0 + Val1; }
    if Val0 + Val1 == N {
        pObj.fPhase = 1;
        return 1;
    }
    assert(false, "0");
    return -1;
}
func Ga2_ManCheckNodesAnd(p *Gia_Man_t, vNodes *Vec_Int_t) int32 {
    var pObj *Gia_Obj_t;
    var i int32;
    Gia_ManForEachObjVec( vNodes, p, pObj, i )
        if ( (!Gia_ObjFanin0(pObj).fPhase && Gia_ObjFaninC0(pObj)) || 
             (!Gia_ObjFanin1(pObj).fPhase && Gia_ObjFaninC1(pObj)) )
            return 0;
    return 1;
}
func Ga2_ManCollectNodes_rec(p *Gia_Man_t, pObj *Gia_Obj_t, vNodes *Vec_Int_t, fFirst int32) {
    if pObj.fPhase && !(fFirst != 0) {
        return; }
    assert(Gia_ObjIsAnd(pObj), "Gia_ObjIsAnd(pObj)");
    Ga2_ManCollectNodes_rec( p, Gia_ObjFanin0(pObj), vNodes, 0 );
    Ga2_ManCollectNodes_rec( p, Gia_ObjFanin1(pObj), vNodes, 0 );
    Vec_IntPush( vNodes, Gia_ObjId(p, pObj) );

}
func Ga2_ManCollectLeaves_rec(p *Gia_Man_t, pObj *Gia_Obj_t, vLeaves *Vec_Int_t, fFirst int32) {
    if pObj.fPhase && !(fFirst != 0) {
        Vec_IntPushUnique( vLeaves, Gia_ObjId(p, pObj) );
        return;
    }
    assert(Gia_ObjIsAnd(pObj), "Gia_ObjIsAnd(pObj)");
    Ga2_ManCollectLeaves_rec( p, Gia_ObjFanin0(pObj), vLeaves, 0 );
    Ga2_ManCollectLeaves_rec( p, Gia_ObjFanin1(pObj), vLeaves, 0 );
}
var spStatic_Ga2_ManMarkup_uTruth5 [5]uint32 = [5]uint32{ 0xAAAAAAAA, 0xCCCCCCCC, 0xF0F0F0F0, 0xFF00FF00, 0xFFFF0000 };
func Ga2_ManMarkup(p *Gia_Man_t, N int32, fSimple int32) int32 {

//    abctime clk = Abc_Clock();
    var vLeaves *Vec_Int_t;
    var pObj *Gia_Obj_t;
    var i, k, Leaf, CountMarks int32;

    vLeaves = Vec_IntAlloc( 100 );

    if fSimple != 0 {
        Gia_ManForEachObj( p, pObj, i )
            pObj.fPhase = !Gia_ObjIsCo(pObj);

    } else {
        // label nodes with multiple fanouts and inputs MUXes
        Gia_ManForEachObj( p, pObj, i )
        {
            pObj.Value = 0;
            if !Gia_ObjIsAnd(pObj) {
                continue; }
            Gia_ObjFanin0(pObj).Value++;
            Gia_ObjFanin1(pObj).Value++;
            if !Gia_ObjIsMuxType(pObj) {
                continue; }
            Gia_ObjFanin0(Gia_ObjFanin0(pObj)).Value++;
            Gia_ObjFanin1(Gia_ObjFanin0(pObj)).Value++;
            Gia_ObjFanin0(Gia_ObjFanin1(pObj)).Value++;
            Gia_ObjFanin1(Gia_ObjFanin1(pObj)).Value++;
        }
        Gia_ManForEachObj( p, pObj, i )
        {
            pObj.fPhase = 0;
            if Gia_ObjIsAnd(pObj) {
                pObj.fPhase = (pObj.Value > 1);
            } else if Gia_ObjIsCo(pObj) {
                Gia_ObjFanin0(pObj).fPhase = 1;
            } else { 
                pObj.fPhase = 1; }
        } 
        // add marks when needed
        Gia_ManForEachAnd( p, pObj, i )
        {
            if !pObj.fPhase {
                continue; }
            Vec_IntClear( vLeaves );
            Ga2_ManCollectLeaves_rec( p, pObj, vLeaves, 1 );
            if Vec_IntSize(vLeaves) > N {
                Ga2_ManBreakTree_rec( p, pObj, 1, N ); }
        }
    }

    // verify that the tree is split correctly
    Vec_IntFreeP( &p.vMapping );
    p.vMapping = Vec_IntStart( Gia_ManObjNum(p) );
    Gia_ManForEachRo( p, pObj, i )
    {
        var pObjRi *Gia_Obj_t  = Gia_ObjRoToRi(p, pObj);
        assert(pObj.fPhase, "pObj.fPhase");
        assert(Gia_ObjFanin0(pObjRi).fPhase, "Gia_ObjFanin0(pObjRi).fPhase");
        // create map
        Vec_IntWriteEntry( p.vMapping, Gia_ObjId(p, pObj), Vec_IntSize(p.vMapping) );
        Vec_IntPush( p.vMapping, 1 );
        Vec_IntPush( p.vMapping, Gia_ObjFaninId0p(p, pObjRi) );
        Vec_IntPush( p.vMapping, Gia_ObjFaninC0(pObjRi) ? 0x55555555 : 0xAAAAAAAA );
        Vec_IntPush( p.vMapping, -1 );  // placeholder for ref counter
    }
    CountMarks = Gia_ManRegNum(p);
    Gia_ManForEachAnd( p, pObj, i )
    {
        if !pObj.fPhase {
            continue; }
        Vec_IntClear( vLeaves );
        Ga2_ManCollectLeaves_rec( p, pObj, vLeaves, 1 );
        assert(Vec_IntSize(vLeaves) <= N, "Vec_IntSize(vLeaves) <= N");
        // create map
        Vec_IntWriteEntry( p.vMapping, i, Vec_IntSize(p.vMapping) );
        Vec_IntPush( p.vMapping, Vec_IntSize(vLeaves) );
        Vec_IntForEachEntry( vLeaves, Leaf, k )
        {            
            Vec_IntPush( p.vMapping, Leaf );
            Gia_ManObj(p, Leaf).Value = spStatic_Ga2_ManMarkup_uTruth5[k];
            assert(Gia_ManObj(p, Leaf).fPhase, "Gia_ManObj(p, Leaf).fPhase");
        }
        Vec_IntPush( p.vMapping,  int32(Ga2_ObjComputeTruth_rec( p, pObj, 1 )) );
        Vec_IntPush( p.vMapping, -1 );  // placeholder for ref counter
        CountMarks++;
    }
//    Abc_PrintTime( 1, "Time", Abc_Clock() - clk );
    Vec_IntFree( vLeaves );
    Gia_ManCleanValue( p );
    return CountMarks;
}
func Ga2_ManComputeTest(p *Gia_Man_t) {
    var clk abctime;
//    unsigned uTruth;
    var pObj *Gia_Obj_t;
    var i, Counter int32;
    clk = Abc_Clock();
    Ga2_ManMarkup( p, 5, 0 );
    Abc_PrintTime( 1, "Time", Abc_Clock() - clk );
    Gia_ManForEachAnd( p, pObj, i )
    {
        if !pObj.fPhase {
            continue; }
//        uTruth = Ga2_ObjTruth( p, pObj );
//        printf( "%6d : ", Counter );
//        Kit_DsdPrintFromTruth( &uTruth, Ga2_ObjLeaveNum(p, pObj) ); 
//        printf( "\n" );
        Counter++;
